#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

// 4-direction movement
const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

struct FlowEdge {
    int v, u;
    ll cap, flow;
    FlowEdge(int v, int u, ll cap) : v(v), u(u), cap(cap), flow(0) {}
};

struct Dinic {
    const ll flow_inf = 1e18;
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    int n;
    int s, t;
    vector<int> level, ptr;
    queue<int> q;

    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add_edge(int v, int u, ll cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(edges.size() - 2);
        adj[u].push_back(edges.size() - 1);
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int id : adj[v]) {
                auto& e = edges[id];
                if (e.cap - e.flow <= 0 || level[e.u] != -1) continue;
                level[e.u] = level[v] + 1;
                q.push(e.u);
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, ll pushed) {
        if (pushed == 0) return 0;
        if (v == t) return pushed;
        for (int& cid = ptr[v]; cid < (int)adj[v].size(); cid++) {
            int id = adj[v][cid];
            auto& e = edges[id];
            if (level[e.u] != level[v] + 1 || e.cap - e.flow <= 0) continue;
            ll tr = dfs(e.u, min(pushed, e.cap - e.flow));
            if (tr == 0) continue;
            e.flow += tr;
            edges[id ^ 1].flow -= tr;
            return tr;
        }
        return 0;
    }

    ll flow() {
        ll max_flow = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(s, flow_inf)) {
                max_flow += pushed;
            }
        }
        return max_flow;
    }
};

int n, t_val;
string sci[15];
string cap[15];
int dist[15][15];

bool valid(int x, int y) {
    return x >= 0 && y >= 0 && x < n && y < n && sci[x][y] != 'Y' && sci[x][y] != 'Z';
}

void bfs_init(int sx, int sy) {
    memset(dist, -1, sizeof(dist));
    queue<pii> q;
    q.push({sx, sy});
    dist[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (valid(nx, ny) && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (dist[i][j] == -1) dist[i][j] = 1000000000;
}

int memo[65][12][12][12][12];
bool vis[65][12][12][12][12];

bool can_reach(int step, int x0, int y0, int x, int y) {
    if (dist[x0][y0] < step) return false;
    if (x0 == x && y0 == y) return true;
    if (step >= t_val) return false;
    if (dist[x0][y0] <= step) return false;
    if (vis[step][x0][y0][x][y]) return memo[step][x0][y0][x][y];
    vis[step][x0][y0][x][y] = true;
    for (int i = 0; i < 4; ++i) {
        int nx = x0 + dx[i], ny = y0 + dy[i];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (sci[nx][ny] == 'Y' || sci[nx][ny] == 'Z') continue;
        if (can_reach(step + 1, nx, ny, x, y)) {
            memo[step][x0][y0][x][y] = true;
            return true;
        }
    }
    memo[step][x0][y0][x][y] = false;
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    memset(memo, -1, sizeof(memo));
    cin >> n >> t_val;
    for (int i = 0; i < n; ++i) cin >> sci[i];
    for (int i = 0; i < n; ++i) cin >> cap[i];

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (sci[i][j] == 'Z') {
                bfs_init(i, j);
                goto done_z;
            }
        }
    }
done_z:

    vector<pii> sources, caps;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (sci[i][j] != 'Z' && sci[i][j] != 'Y' && sci[i][j] != '0')
                sources.push_back({i, j});
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (cap[i][j] != 'Z' && cap[i][j] != 'Y' && cap[i][j] != '0')
                caps.push_back({i, j});

    int total_nodes = sources.size() + caps.size() + 2;
    Dinic dinic(total_nodes, 0, total_nodes - 1);

    for (int i = 0; i < sources.size(); ++i) {
        ll c = sci[sources[i].first][sources[i].second] - '0';
        dinic.add_edge(0, i + 1, c);
    }
    for (int i = 0; i < caps.size(); ++i) {
        ll c = cap[caps[i].first][caps[i].second] - '0';
        dinic.add_edge(sources.size() + 1 + i, total_nodes - 1, c);
    }

    for (int i = 0; i < sources.size(); ++i)
        for (int j = 0; j < caps.size(); ++j)
            if (can_reach(0, sources[i].first, sources[i].second, caps[j].first, caps[j].second))
                dinic.add_edge(i + 1, sources.size() + 1 + j, 10000000LL);

    cout << dinic.flow() << '\n';
    return 0;
}
